"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was.
"""
import os
import shutil
import stat
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755


MAX_LINK_HOPS = 40  # as many symbolic links as Linux follows in one path before it gives up with ELOOP


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest, a link that points outside it, a name listed twice, any other kind of member or an
    archive over the size limits raises UnsafeArchive, and then nothing has been written.

    Where a member lands and where a link leads are worked out the way the filesystem will see them once the
    members before it (and, for links, every member) have been written: links already in dest and links made by
    earlier members are followed, not read as plain text. So a chain such as `a -> .`, `b -> a/a/../..` or a file
    written through a link that leads out is refused, while links between the archive's own files still work."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    with tarfile.open(tar_path) as tar:
        members = tar.getmembers()
        limits.check(members)
        plan = plan_members(root, members)
        for member, target in plan:
            write_member(tar, member, target)
    return [paths.clean_name(m.name) for m in members]


class _Tree:
    """dest as it will be after each member is written, without writing anything: what the archive has added so
    far over what was already on disk. Paths are tuples of names relative to root, with no links in them."""

    def __init__(self, root):
        self.root = root
        self.added = {}  # parts -> "dir" | "file" | ("link", linkname)

    def kind(self, parts):
        """"dir", "file", ("link", linkname), "other" or None (nothing there) for a link-free path."""
        if parts in self.added:
            return self.added[parts]
        path = os.path.join(self.root, *parts)
        try:
            st = os.lstat(path)
        except FileNotFoundError:
            return None
        except OSError as e:
            raise UnsafeArchive(f"can't look at {'/'.join(parts)} in the destination: {e}") from None
        if stat.S_ISLNK(st.st_mode):
            return ("link", os.readlink(path))
        if stat.S_ISDIR(st.st_mode):
            return "dir"
        if stat.S_ISREG(st.st_mode):
            return "file"
        return "other"

    def resolve(self, start, rel, what, follow_last=True, hops=None):
        """The link-free parts that the relative path rel, read from the link-free folder start, leads to, following
        links the way the kernel does. UnsafeArchive if it leaves root, loops or goes through something that isn't
        a folder. Parts past the first missing one are taken as they are, as folders yet to be made."""
        hops = hops if hops is not None else [0]
        cur = list(start)
        names = [n for n in rel.split("/") if n not in ("", ".")]
        missing = False
        for i, name in enumerate(names):
            last = i == len(names) - 1
            if name == "..":
                if not cur:
                    raise UnsafeArchive(f"{what} leads outside the destination")
                cur.pop()
                if missing:
                    missing = bool(cur) and self.kind(tuple(cur)) is None
                continue
            cur.append(name)
            if missing:
                continue
            kind = self.kind(tuple(cur))
            if kind is None:
                missing = True
            elif isinstance(kind, tuple):
                if last and not follow_last:
                    continue
                hops[0] += 1
                if hops[0] > MAX_LINK_HOPS:
                    raise UnsafeArchive(f"{what} goes through too many links")
                linkname = kind[1]
                if not linkname or linkname.startswith("/") or "\x00" in linkname:
                    raise UnsafeArchive(f"{what} goes through {'/'.join(cur)}, a link to an absolute path")
                cur.pop()
                cur = list(self.resolve(tuple(cur), linkname, what, True, hops))
                if self.kind(tuple(cur)) is None:
                    missing = True
            elif kind != "dir" and not last:
                raise UnsafeArchive(f"{what} goes through {'/'.join(cur)}, which isn't a folder")
        return tuple(cur)

    def add(self, parts, kind):
        for i in range(1, len(parts)):
            self.added.setdefault(parts[:i], "dir")  # makedirs makes any folder that's missing on the way
        self.added[parts] = kind


def plan_members(root, members):
    """[(member, the absolute path it goes to), ...] once every member has passed, or UnsafeArchive.

    The path a member goes to has no links in it, so writing there can't be steered elsewhere by a link."""
    seen = set()
    plan = []
    tree = _Tree(root)
    links = []
    for member in members:
        name = paths.clean_name(member.name)
        if name in seen:
            raise UnsafeArchive(f"{name} is listed twice")
        seen.add(name)
        if member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        if not (member.issym() or member.isfile() or member.isdir()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        if member.issym():
            if not member.linkname or os.path.isabs(member.linkname) or member.linkname.startswith("/"):
                raise UnsafeArchive(f"{name} links to an absolute path")
            if "\x00" in member.linkname:
                raise UnsafeArchive(f"{name} has a bad link target")
            # Written as text, so check it as text too (this is the rule 2.3.0 introduced) ...
            if not paths.is_within(root, paths.link_target(root, name, member.linkname)):
                raise UnsafeArchive(f"{name} links to {member.linkname}, outside the destination")
        what = f"{name}"
        # Where the member really lands: its folder with every link on the way followed, as dest will be then.
        parent, _, base = name.rpartition("/")
        try:
            folder = tree.resolve((), parent, what) if parent else ()
        except UnsafeArchive as e:
            raise UnsafeArchive(f"{e} (it would be written outside the destination)") from None
        if folder and tree.kind(folder) not in (None, "dir"):
            raise UnsafeArchive(f"{name} would be written inside {'/'.join(folder)}, which isn't a folder")
        parts = folder + (base,)
        there = tree.kind(parts)
        if member.isdir():
            if isinstance(there, tuple):  # an existing link to a folder: makedirs is happy with it, so are we
                parts = tree.resolve(folder, base, what)
                there = tree.kind(parts)
            if there not in (None, "dir"):
                raise UnsafeArchive(f"{name} is a folder, but something else is already there")
            tree.add(parts, "dir")
        else:
            if there is not None:
                raise UnsafeArchive(f"{name} would replace something already there")
            if member.issym():
                tree.add(parts, ("link", member.linkname))
                links.append((name, folder, member.linkname))
            else:
                tree.add(parts, "file")
        target = os.path.join(root, *parts)
        if not paths.is_within(root, target):
            raise UnsafeArchive(f"{name} would be written outside the destination")
        plan.append((member, target))
    # ... and as the filesystem will follow it once everything is written, links made later included.
    for name, folder, linkname in links:
        tree.resolve(folder, linkname, f"{name} -> {linkname}")
    return plan


def write_member(tar, member, target):
    """Write member at target, a path plan_members has checked and that has no links in it."""
    if member.isdir():
        os.makedirs(target, exist_ok=True)
        return
    os.makedirs(os.path.dirname(target), exist_ok=True)
    if member.issym():
        os.symlink(member.linkname, target)
        return
    fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), FILE_MODE)
    with tar.extractfile(member) as src, os.fdopen(fd, "wb") as out:
        shutil.copyfileobj(src, out)
    os.chmod(target, EXEC_MODE if member.mode & 0o100 else FILE_MODE)

