import sqlite3

from payments import gateway, service

IDEMPOTENCY_HEADER = "idempotency-key"


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}.

    With an Idempotency-Key header, a retry with the same key and body gets the original
    response and is not charged again; the same key with a different body gets 409.
    """
    body = request.get("body") or {}
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    key = _idempotency_key(request.get("headers"))
    if key is None:
        return _create(conn, customer_id, cents, None)
    # Take the write lock before the lookup, so two retries that race cannot both charge.
    conn.execute("BEGIN IMMEDIATE")
    try:
        row = _find(conn, key)
        if row is None:
            return _create(conn, customer_id, cents, key)
        return _repeat(row, customer_id, cents)
    finally:
        # Ends the transaction and releases the lock on every path. After a successful
        # create, service.create_payment has already committed, so this does nothing.
        conn.rollback()


def _idempotency_key(headers):
    """Return the Idempotency-Key value, or None if it is missing or blank. Header names are case-insensitive."""
    for name, value in (headers or {}).items():
        if name.lower() == IDEMPOTENCY_HEADER and value and value.strip():
            return value.strip()
    return None


def _find(conn, key):
    return conn.execute(
        "SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?", (key,)).fetchone()


def _repeat(row, customer_id, cents):
    """Answer a key that was already used: replay the original payment, or refuse a different request."""
    if row["customer_id"] != customer_id or row["cents"] != cents:
        return 409, {"error": "idempotency key reused"}
    return 201, {"id": row["id"], "customer_id": row["customer_id"], "cents": row["cents"],
                 "charge_id": row["charge_id"]}


def _create(conn, customer_id, cents, key):
    try:
        payment = service.create_payment(conn, customer_id, cents, idempotency_key=key)
    except service.UnknownCustomer:
        return 404, {"error": "no such customer"}
    except gateway.Declined as e:
        conn.rollback()
        return 402, {"error": f"declined: {e}"}
    except sqlite3.IntegrityError:
        # Backstop: the key was stored after our lookup. The write lock should prevent this.
        if key is None:
            raise
        conn.rollback()
        row = _find(conn, key)
        if row is None:
            raise
        return _repeat(row, customer_id, cents)
    return 201, payment

