"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was.

Two things keep a link from being used against us:

* Checking happens against the tree the archive will build, not the one on disk now: a link is followed through
  the other links of the archive (paths.resolve_link), so `a -> b/..` can't climb out because `b` turns out to be
  a link to somewhere shallower. And no member may be written under a link, so "make a link, then write through
  it" has no way in.
* Writing happens relative to open folder handles, never following a link (O_NOFOLLOW), so a folder swapped for
  a link after the check can't redirect a write either. If anything still goes wrong, what was written is removed.
"""
import errno
import os
import shutil
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755

DIR_FLAGS = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
RACE_ERRORS = (errno.ELOOP, errno.ENOTDIR, errno.EEXIST, errno.ENOENT, errno.EISDIR)


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest or under a link, a link that points outside it, a name listed twice, a name that is
    already there, any other kind of member or an archive over the size limits raises UnsafeArchive, and then
    nothing has been written."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    with tarfile.open(tar_path) as tar:
        members = tar.getmembers()
        limits.check(members)
        plan = plan_members(root, members)
        write_all(tar, root, plan)
    return [paths.clean_name(m.name) for m in members]


def plan_members(root, members):
    """[(member, [name parts]), ...] once every member has passed, or UnsafeArchive."""
    names = []
    kinds = {}  # clean name -> "dir" | "file" | the target of a link
    for member in members:
        name = paths.clean_name(member.name)
        if name in kinds:
            raise UnsafeArchive(f"{name} is listed twice")
        if member.issym():
            kinds[name] = paths.clean_linkname(name, member.linkname)
        elif member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        elif member.isdir():
            kinds[name] = "dir"
        elif member.isfile():
            kinds[name] = "file"
        else:
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        names.append(name)

    def lookup(parts):
        """The target of the link at parts, as it will be once extracted: the archive's own links, and for
        anything it doesn't name, the links already in the destination."""
        name = "/".join(parts)
        if name in kinds:
            kind = kinds[name]
            return None if kind in ("dir", "file") else kind
        path = paths.under(root, name)
        if os.path.islink(path):
            return os.readlink(path)
        return None

    plan = []
    for member, name in zip(members, names):
        parts = name.split("/")
        check_parents(root, kinds, name, parts)
        check_not_there(root, member, name)
        if member.issym():
            where = paths.resolve_link(parts[:-1], member.linkname, lookup)
            if where is None:
                raise UnsafeArchive(f"{name} links to {member.linkname}, outside the destination")
        plan.append((member, parts))
    return plan


def check_parents(root, kinds, name, parts):
    """UnsafeArchive unless every folder above name is, or will be, a real folder inside root: not a link or a file
    from the archive, and not a link or a file already in the destination."""
    for i in range(1, len(parts)):
        above = "/".join(parts[:i])
        kind = kinds.get(above)
        if kind == "dir":
            continue
        if kind == "file":
            raise UnsafeArchive(f"{name} would be written inside the file {above}")
        if kind is not None:
            raise UnsafeArchive(f"{name} would be written through the link {above}")
        path = paths.under(root, above)
        if os.path.islink(path):
            raise UnsafeArchive(f"{name} would be written through the link {above} already in the destination")
        if os.path.lexists(path) and not os.path.isdir(path):
            raise UnsafeArchive(f"{name} would be written inside {above}, which isn't a folder")


def check_not_there(root, member, name):
    """An archive may add to the destination but not replace or overwrite anything in it."""
    path = paths.under(root, name)
    if not os.path.lexists(path):
        return
    if member.isdir() and os.path.isdir(path) and not os.path.islink(path):
        return
    raise UnsafeArchive(f"{name} is already in the destination")


def write_all(tar, root, plan):
    """Write the planned members under root; if anything fails part way, remove what was written."""
    root_fd = os.open(root, DIR_FLAGS)
    created = []  # (kind, parts), in the order created
    try:
        try:
            for member, parts in plan:
                write_member(tar, root_fd, member, parts, created)
        except BaseException as e:
            rollback(root_fd, created)
            if isinstance(e, OSError) and e.errno in RACE_ERRORS:
                raise UnsafeArchive(f"the destination changed while the archive was being extracted: {e}") from None
            raise
    finally:
        os.close(root_fd)


def open_dir(root_fd, parts, created=None):
    """A handle on the folder at parts under root_fd, made if it isn't there; no link is ever followed."""
    fd = os.dup(root_fd)
    try:
        for i, part in enumerate(parts):
            if created is not None:
                try:
                    os.mkdir(part, dir_fd=fd)
                    created.append(("dir", parts[:i + 1]))
                except FileExistsError:
                    pass
            nxt = os.open(part, DIR_FLAGS, dir_fd=fd)
            os.close(fd)
            fd = nxt
        return fd
    except BaseException:
        os.close(fd)
        raise


def write_member(tar, root_fd, member, parts, created):
    if member.isdir():
        os.close(open_dir(root_fd, parts, created))
        return
    parent = open_dir(root_fd, parts[:-1], created)
    try:
        name = parts[-1]
        if member.issym():
            os.symlink(member.linkname, name, dir_fd=parent)
            created.append(("file", parts))
            return
        fd = os.open(name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o666, dir_fd=parent)
        created.append(("file", parts))
        with os.fdopen(fd, "wb") as out, tar.extractfile(member) as src:
            shutil.copyfileobj(src, out)
            out.flush()
            os.fchmod(out.fileno(), EXEC_MODE if member.mode & 0o100 else FILE_MODE)
    finally:
        os.close(parent)


def rollback(root_fd, created):
    """Remove what write_all created, newest first. Best effort: it never follows a link and never raises."""
    for kind, parts in reversed(created):
        try:
            parent = open_dir(root_fd, parts[:-1])
        except OSError:
            continue
        try:
            if kind == "dir":
                os.rmdir(parts[-1], dir_fd=parent)
            else:
                os.unlink(parts[-1], dir_fd=parent)
        except OSError:
            pass
        finally:
            os.close(parent)

