"""Path rules for archive members. A member's name is a POSIX path relative to the archive's root."""
import os
import posixpath

from .errors import UnsafeArchive

MAX_NAME = 1024


def clean_name(name):
    """The member name as a relative path with no empty or "." parts. UnsafeArchive for an absolute name, a drive
    letter, a ".." part, a backslash or a NUL."""
    if not isinstance(name, str) or not name or "\x00" in name or "\\" in name:
        raise UnsafeArchive(f"bad member name {name!r}")
    if name.startswith("/") or (len(name) > 1 and name[1] == ":"):
        raise UnsafeArchive(f"{name} is an absolute path")
    parts = [part for part in name.split("/") if part not in ("", ".")]
    if not parts:
        raise UnsafeArchive(f"bad member name {name!r}")
    if ".." in parts:
        raise UnsafeArchive(f"{name} climbs out with ..")
    clean = "/".join(parts)
    if len(clean) > MAX_NAME:
        raise UnsafeArchive(f"a member name is longer than {MAX_NAME} characters")
    return clean


def is_within(root, path):
    """Whether path is root or under it; both absolute and normalized."""
    return path == root or path.startswith(root.rstrip(os.sep) + os.sep)


def clean_linkname(name, linkname):
    """The target of the link called name, as a POSIX path split on "/". UnsafeArchive for an empty or absolute
    target, a drive letter, a backslash or a NUL. A ".." is fine here; resolve_link judges where it leads."""
    if not isinstance(linkname, str) or not linkname or "\x00" in linkname or "\\" in linkname:
        raise UnsafeArchive(f"{name} has a bad link target {linkname!r}")
    if linkname.startswith("/") or (len(linkname) > 1 and linkname[1] == ":"):
        raise UnsafeArchive(f"{name} links to an absolute path")
    return linkname


MAX_HOPS = 40


def resolve_link(start, linkname, lookup):
    """Follow a link the way the kernel will once everything is extracted.

    start is the list of path parts of the folder holding the link (relative to the destination, already known to
    be real folders, not links); linkname is its target. lookup(parts) returns the target of the link at that
    relative path, or None if there is no link there. Links met on the way are followed, so a ".." after a link
    climbs out of the folder the link points to, not out of the folder it sits in.

    Return the resolved parts, or None if the path climbs out of the destination. A path that loops or runs into
    something that isn't a folder can't lead anywhere, so it counts as inside."""
    current = list(start)
    queue = linkname.split("/")[::-1]
    hops = 0
    while queue:
        part = queue.pop()
        if part in ("", "."):
            continue
        if part == "..":
            if not current:
                return None
            current.pop()
            continue
        current.append(part)
        target = lookup(current)
        if target is None:
            continue
        hops += 1
        if hops > MAX_HOPS:
            return current
        if target.startswith("/"):
            return None
        current.pop()
        queue.extend(target.split("/")[::-1])
    return current


def under(root, name):
    """The absolute path a member name maps to under root."""
    return os.path.join(root, *name.split("/"))

