import hashlib
import json

from payments import gateway, service


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}.

    An optional Idempotency-Key header makes a retry safe: the first outcome for a key is
    stored in the database and replayed for the same body; a different body gets 409.
    """
    headers = request.get("headers") or {}
    body = request.get("body") or {}
    key = _idempotency_key(headers)
    if key is None:
        return _create(conn, body)
    if key == "":
        return 400, {"error": "Idempotency-Key must not be empty"}
    return _keyed(conn, key, body)


def _idempotency_key(headers):
    """The Idempotency-Key header value, matched without regard to case; None if absent."""
    for name, value in headers.items():
        if name.lower() == "idempotency-key":
            return str(value).strip()
    return None


def _create(conn, body):
    """A request without a key: run it and commit whatever it left behind."""
    status, response = _attempt(conn, body)
    conn.commit()
    return status, response


def _keyed(conn, key, body):
    """Look up, charge and store the outcome in one write transaction.

    BEGIN IMMEDIATE takes the database write lock before the lookup, so two requests with
    the same key, on any worker or host, run one after the other: the second sees the
    first one's stored outcome and charges nothing.
    """
    request_hash = _fingerprint(body)
    conn.execute("BEGIN IMMEDIATE")
    try:
        row = conn.execute(
            "SELECT request_hash, status, response FROM idempotency_keys WHERE key = ?", (key,)
        ).fetchone()
        if row is not None:
            stored_hash, status, response = row
            conn.rollback()  # nothing was written; end the transaction and release the lock
            if stored_hash != request_hash:
                return 409, {"error": "idempotency key reused"}
            return status, json.loads(response)
        status, response = _attempt(conn, body)
        conn.execute(
            "INSERT INTO idempotency_keys (key, request_hash, status, response) VALUES (?, ?, ?, ?)",
            (key, request_hash, status, json.dumps(response)),
        )
        conn.commit()
        return status, response
    except BaseException:
        conn.rollback()
        raise


def _attempt(conn, body):
    """Validate and charge without committing; return (status, response).

    A failed attempt (unknown customer, decline) is undone with a savepoint, so only the
    response is left behind. The savepoint lets this run inside a larger transaction
    without rolling that transaction back.
    """
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    conn.execute("SAVEPOINT attempt")
    try:
        payment = service.create_payment(conn, customer_id, cents)
    except service.UnknownCustomer:
        status, response = 404, {"error": "no such customer"}
    except gateway.Declined as e:
        status, response = 402, {"error": f"declined: {e}"}
    else:
        conn.execute("RELEASE attempt")
        return 201, payment
    conn.execute("ROLLBACK TO attempt")
    conn.execute("RELEASE attempt")
    return status, response


def _fingerprint(body):
    """A stable hash of the request body, so the same body always matches."""
    canonical = json.dumps(body, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()

