from payments import gateway, service


def _idempotency_key(headers):
    """Return the Idempotency-Key header (names are case-insensitive), or None if absent or blank."""
    for name, value in (headers or {}).items():
        if isinstance(name, str) and name.lower() == "idempotency-key":
            if isinstance(value, str) and value.strip():
                return value.strip()
    return None


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}.

    An optional Idempotency-Key header makes retries safe: a repeat with the same body
    gets the original 201 response without a new charge; a different body gets 409.
    """
    body = request.get("body") or {}
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    key = _idempotency_key(request.get("headers"))
    try:
        payment = service.create_payment(conn, customer_id, cents, idempotency_key=key)
    except service.IdempotencyKeyReused:
        return 409, {"error": "idempotency key reused"}
    except service.UnknownCustomer:
        return 404, {"error": "no such customer"}
    except gateway.Declined as e:
        conn.rollback()
        return 402, {"error": f"declined: {e}"}
    return 201, payment

