import sqlite3

from payments import gateway


class UnknownCustomer(Exception):
    pass


class IdempotencyKeyReused(Exception):
    """The idempotency key was already used for a payment with a different body."""


def _as_dict(row):
    return {"id": row["id"], "customer_id": row["customer_id"], "cents": row["cents"], "charge_id": row["charge_id"]}


def _replay(conn, idempotency_key, customer_id, cents):
    """Return the stored payment for this key, None if there is none; raise if the body differs."""
    row = conn.execute("SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
                       (idempotency_key,)).fetchone()
    if row is None:
        return None
    if (row["customer_id"], row["cents"]) != (customer_id, cents):
        raise IdempotencyKeyReused(idempotency_key)
    return _as_dict(row)


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency_key, a payment already stored under that key is returned
    instead of charging again (IdempotencyKeyReused if its customer or amount differ).
    """
    if idempotency_key is not None:
        existing = _replay(conn, idempotency_key, customer_id, cents)
        if existing is not None:
            return existing
    if conn.execute("SELECT 1 FROM customers WHERE id = ?", (customer_id,)).fetchone() is None:
        raise UnknownCustomer(customer_id)
    charge_id = gateway.charge(conn, cents)
    try:
        cur = conn.execute(
            "INSERT INTO payments (customer_id, cents, charge_id, idempotency_key) VALUES (?, ?, ?, ?)",
            (customer_id, cents, charge_id, idempotency_key))
    except sqlite3.IntegrityError:
        # A concurrent request with the same key stored its payment first. Roll back our
        # charge (gateway_log is in this transaction) and answer with the winner's payment.
        conn.rollback()
        if idempotency_key is not None:
            existing = _replay(conn, idempotency_key, customer_id, cents)
            if existing is not None:
                return existing
        raise
    conn.commit()
    return {"id": cur.lastrowid, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}

