from billing import rules


def balances(conn) -> dict[int, int]:
    """Each account's balance in cents, {account_id: cents}: what its invoices that aren't voided ask for, minus the payments on them that rules.counts accepts. Every account is in the result, 0 when it has nothing to pay."""
    account_ids = [account_id for (account_id,) in conn.execute("SELECT id FROM accounts").fetchall()]
    # Invoices and payments are fetched in one query each and grouped in Python. The ORDER BY clauses
    # match the order the per-account queries used to return rows in, so running sums are built in the same order.
    invoices = conn.execute(
        "SELECT id, account_id, amount_cents FROM invoices"
        " WHERE voided = 0 AND account_id IN (SELECT id FROM accounts) ORDER BY account_id, id").fetchall()
    payments_by_invoice = {}
    for invoice_id, paid, status, method in conn.execute(
            "SELECT p.invoice_id, p.amount_cents, p.status, p.method FROM payments p"
            " JOIN invoices i ON i.id = p.invoice_id WHERE i.voided = 0 ORDER BY p.id").fetchall():
        payments_by_invoice.setdefault(invoice_id, []).append((paid, status, method))
    owed = {}
    for invoice_id, account_id, cents in invoices:
        total = owed.get(account_id, 0) + cents
        for paid, status, method in payments_by_invoice.get(invoice_id, ()):
            if rules.counts(status, method):
                total -= paid
        owed[account_id] = total
    return {account_id: owed.get(account_id, 0) for account_id in account_ids}

