"""Migrate a v2 export to the v3 format.

migrate(src, accounts, dst) reads the v2 export at src (docs/FORMAT_V2.md) and the accounts file at accounts
(data/accounts.json shows the shape), writes the v3 file at dst (docs/FORMAT_V3.md, "Migrating from v2") and
returns the number of records written.

The export is streamed, never held whole. v3 wants its records sorted by account, posted_at, id, and the v2 lines
come in no useful order, so the migration is an external sort in three steps:

1. every line is converted (and every line is checked, superseded revisions included) and the converted records
   are sorted by (id, rev, line number) in runs of RUN_RECORDS that are spilled to scratch files;
2. the merged stream is grouped by id, and each id's last record is its current revision;
3. those records are sorted by (account, posted_at, id) the same way and written to dst.

Memory is bounded by RUN_RECORDS and MERGE_WIDTH, not by the size of the export. Output goes to dst.tmp and is
renamed to dst only when every record has been written, so a failed migration leaves dst untouched.
"""
import collections
import heapq
import itertools
import json
import os
import tempfile

from . import kinds, money, timefmt, v3
from .accounts import load as load_accounts
from .errors import FormatError, MigrationError
from .v2 import check as check_v2

RUN_RECORDS = 200_000  # records sorted in memory at once
MERGE_WIDTH = 64       # run files open at once while merging


def migrate(src, accounts, dst):
    held = load_accounts(accounts)
    dst = os.fspath(dst)
    scratch_parent = os.path.dirname(os.path.abspath(dst))
    tmp = dst + ".tmp"
    with tempfile.TemporaryDirectory(dir=scratch_parent) as scratch:
        by_id = _sorted(_converted(src, held), lambda item: (item["id"], item["rev"], item["line"]), scratch)
        ordered = _sorted(_current(by_id), v3.order_key, scratch)
        try:
            with open(tmp, "w", encoding="utf-8", newline="\n") as out:
                count = _write(out, ordered)
            os.replace(tmp, dst)
        except BaseException:
            if os.path.exists(tmp):
                os.remove(tmp)
            raise
    return count


def _converted(src, held):
    """One item per v2 line, in file order: {"id", "rev", "line", "record"} with record a v3 record."""
    with open(src, "rb") as f:
        for number, raw in enumerate(f, 1):
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError as e:
                raise MigrationError(f"not UTF-8 ({e.reason})", number) from None
            if not text.strip():
                continue
            try:
                record = json.loads(text)
            except ValueError as e:
                raise MigrationError(f"not JSON ({e})", number) from None
            try:
                check_v2(record, None)
            except FormatError as e:
                raise MigrationError(str(e), number) from None
            yield {"id": record["id"], "rev": record["rev"], "line": number,
                   "record": _to_v3(record, number, held)}


def _to_v3(rec, line, held):
    """The v3 record for one v2 line. MigrationError when the line can't be migrated."""
    account = held.get(rec["account"])
    if account is None:
        raise MigrationError(f"account {rec['account']!r} isn't in the accounts file", line)

    kind = kinds.LEGACY.get(rec["kind"], rec["kind"])
    if kind not in kinds.TYPES:
        raise MigrationError(f"unknown kind {rec['kind']!r}", line)

    # A null currency means the account's own currency; a non-null one is the entry's, even if it differs.
    currency = account.currency if rec["currency"] is None else rec["currency"]
    if not money.is_currency(currency):
        raise MigrationError(f"bad currency {currency!r}", line)

    try:
        minor = money.to_minor(rec["amount"], currency)
    except ValueError as e:
        raise MigrationError(str(e), line) from None
    if minor < 0:
        raise MigrationError(f"amount {rec['amount']} is negative; v2 amounts are positive", line)

    try:
        stamp = timefmt.parse_ts(rec["ts"])
        if stamp.tzinfo is None:
            # A time with no offset is in the account's local time (docs/FORMAT_V2.md, History).
            stamp = stamp.replace(tzinfo=account.tz)
        posted_at = timefmt.to_utc_z(stamp)
    except (ValueError, OverflowError) as e:
        raise MigrationError(f"bad ts {rec['ts']!r} ({e})", line) from None

    try:
        for text in (rec["id"], rec["account"], rec["memo"]):
            text.encode("utf-8")
    except UnicodeEncodeError:
        raise MigrationError("id, account or memo isn't valid UTF-8 text", line) from None

    record = {
        "id": rec["id"],
        "account": rec["account"],
        "type": kind,
        "amount_minor": kinds.SIGN[kind] * minor,
        "currency": currency,
        "posted_at": posted_at,
        "memo": rec["memo"],
        "source_rev": rec["rev"],
    }
    try:
        v3.validate(record)
    except FormatError as e:
        raise MigrationError(str(e), line) from None
    return record


def _current(items):
    """The current revision of each id. items are sorted by id, then rev, then line, so an id's last item is
    its highest rev, and among equal revs the later line, which is the newer one."""
    for _, group in itertools.groupby(items, key=lambda item: item["id"]):
        yield collections.deque(group, maxlen=1)[0]["record"]


def _write(out, records):
    count = 0
    previous = None
    for record in records:
        key = v3.order_key(record)
        if previous is not None and key <= previous:
            raise FormatError(f"internal error: {record['id']!r} is out of order")
        out.write(v3.dump_line(record))
        previous = key
        count += 1
    return count


def _sorted(items, key, scratch):
    """Everything in items, sorted by key, without holding it all in memory. The sort is done when this returns;
    the result is a lazy iterator over the merged runs in scratch."""
    runs = []
    buf = []

    def spill():
        buf.sort(key=key)
        path = _scratch_file(scratch)
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            for item in buf:
                f.write(json.dumps(item, separators=(",", ":")) + "\n")
        runs.append(path)
        buf.clear()

    for item in items:
        buf.append(item)
        if len(buf) >= RUN_RECORDS:
            spill()
    if buf:
        spill()

    while len(runs) > MERGE_WIDTH:
        group, runs = runs[:MERGE_WIDTH], runs[MERGE_WIDTH:]
        merged = _scratch_file(scratch)
        with open(merged, "w", encoding="utf-8", newline="\n") as f:
            for item in _merge(group, key):
                f.write(json.dumps(item, separators=(",", ":")) + "\n")
        for path in group:
            os.remove(path)
        runs.append(merged)

    return _merge(runs, key)


def _merge(paths, key):
    return heapq.merge(*(_read_run(path) for path in paths), key=key)


def _read_run(path):
    with open(path, encoding="utf-8") as f:
        for text in f:
            yield json.loads(text)


def _scratch_file(scratch):
    fd, path = tempfile.mkstemp(dir=scratch, suffix=".jsonl")
    os.close(fd)
    return path

