"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was.
"""
import os
import shutil
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest, a link that points outside it, a name listed twice, any other kind of member or an
    archive over the size limits raises UnsafeArchive, and then nothing has been written."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    with tarfile.open(tar_path) as tar:
        members = tar.getmembers()
        limits.check(members)
        plan = plan_members(root, members)
        for member, target in plan:
            write_member(tar, member, target)
    return [paths.clean_name(m.name) for m in members]


MAX_LINK_HOPS = 40  # the kernel's own limit on the links one path may follow


def plan_members(root, members):
    """[(member, the absolute path it goes to), ...] once every member has passed, or UnsafeArchive.

    Nothing is written during planning, so every check looks at the archive's names and links as they will be, and
    at what is already in the destination. Two rules keep that picture true while the archive is written: no
    member is written through a link (a link's folders are real folders), and every link leads inside root once
    each link on its way is followed the way the kernel follows it."""
    named = {}
    for member in members:
        name = paths.clean_name(member.name)
        if name in named:
            raise UnsafeArchive(f"{name} is listed twice")
        named[name] = member
    links = {}
    for name, member in named.items():
        if member.issym():
            links[name] = paths.clean_link(name, member.linkname)
        elif member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        elif not (member.isfile() or member.isdir()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
    plan = []
    for name, member in named.items():
        for parent in paths.ancestors(name):
            if parent in links:
                raise UnsafeArchive(f"{name} would be written through the link {parent}")
            if parent in named and not named[parent].isdir():
                raise UnsafeArchive(f"{name} would be written inside {parent}, which isn't a folder")
            found = _on_disk(paths.under(root, parent))
            if found == "link":
                raise UnsafeArchive(f"{name} would be written through {parent}, a link already in the destination")
            if found == "other":
                raise UnsafeArchive(f"{name} would be written inside {parent}, which isn't a folder")
        target = paths.under(root, name)
        found = _on_disk(target)
        if found and not (member.isdir() and found == "folder"):
            raise UnsafeArchive(f"{name} is already in the destination")
        if member.issym():
            _check_link(root, links, name, links[name])
        plan.append((member, target))
    return plan


def _on_disk(path):
    """What is at path before anything is written: "link", "folder", "other", or None for nothing."""
    if os.path.islink(path):
        return "link"
    if os.path.isdir(path):
        return "folder"
    return "other" if os.path.lexists(path) else None


def _check_link(root, links, name, linkname):
    """UnsafeArchive unless the link called name, pointing at linkname, leads inside root once each link on the way
    is followed. The folder the link is in is a real folder (see plan_members), so the walk starts there."""
    where = name.split("/")[:-1]
    pending = linkname.split("/")
    hops = 0
    while pending:
        part = pending.pop(0)
        if part in ("", "."):
            continue
        if part == "..":
            if not where:
                raise UnsafeArchive(f"{name} links to {linkname}, outside the destination")
            where.pop()
            continue
        where.append(part)
        target = _link_at(root, links, where)
        if target is None:
            continue
        if target.startswith("/"):
            raise UnsafeArchive(f"{name} leads through {'/'.join(where)}, which links to an absolute path")
        hops += 1
        if hops > MAX_LINK_HOPS:
            raise UnsafeArchive(f"{name} leads through more than {MAX_LINK_HOPS} links")
        where.pop()
        pending = target.split("/") + pending


def _link_at(root, links, parts):
    """The target of the link at the path parts (under root), or None when that is not a link."""
    name = "/".join(parts)
    if name in links:
        return links[name]
    real = os.path.join(root, *parts)
    return os.readlink(real) if os.path.islink(real) else None


def write_member(tar, member, target):
    if member.isdir():
        os.makedirs(target, exist_ok=True)
        return
    os.makedirs(os.path.dirname(target), exist_ok=True)
    if member.issym():
        os.symlink(member.linkname, target)
        return
    with tar.extractfile(member) as src, open(target, "xb") as out:
        shutil.copyfileobj(src, out)
    os.chmod(target, EXEC_MODE if member.mode & 0o100 else FILE_MODE)

